INSERT INTO benefit_items_import VALUES
  ('fubon', '富邦人壽福星雙盈外幣分紅終身保險', 1, '身故', '身故保險金', '取較高：保額 × 1／保單價值', '第十六條被保險人於本契約有效期間內身故者，本公司按下表約定給付身故保險金後，本契約效力即行終止：保單年度給付金額按下列二者之最大值給付：一、身故時之當年度保險金額。1～6二、身故時之保單價值準備金乘上當時保險年齡對應附表一之給付比率所得之數額。按下列三者之最大值給付：一、身故時之當年度保險金額。7～二、身故時之保單價值準備金乘上當時保險年齡對應附表一之給付比率所得之數額。三、身故時之保險金額。要保人選擇改為「減額繳清保險」或辦理減少保險金額者，於計算前項身故保險金而依約定有扣除累計已領之生存保險金之必要時，改以辦理「減額繳清保險」或減少保險金額後，被保險人發生約定保險事故時之保險金額計'),
  ('fubon', '富邦人壽福星雙盈外幣分紅終身保險', 2, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值', '第十七條被保險人於本契約有效期間內致成附表二所列完全失能程度之一者，本公司按下表約定給付完全失能保險金後，本契約效力即行終止：保單年度給付金額1～6按下列二者之最大值給付：PFF11501016/12商品代號：PFF一、完全失能診斷確定時之當年度保險金額。二、完全失能診斷確定時之保單價值準備金乘上當時保險年齡對應附表一之給付比率所得之數額。按下列三者之最大值給付：一、完全失能診斷確定時之當年度保險金額。7～二、完全失能診斷確定時之保單價值準備金乘上當時保險年齡對應附表一之給付比率所得之數額。三、完全失能診斷確定時之保險金額。要保人選擇改為「減額繳清保險」或辦理減少保險金額者，於計算前項完全失能保險金而依約定有扣除累'),
  ('fubon', '富邦人壽紅富美好外幣分紅終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽紅富美好外幣分紅終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十六條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽紅運年代分紅終身保險', 1, '身故', '身故保險金', '分情況（看原文）', '第十四條被保險人於本契約有效且於繳費期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽紅運年代分紅終身保險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十五條被保險人於本契約有效且於繳費期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽智富美家外幣利率變動型終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽智富美家外幣利率變動型終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十六條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽智富美家外幣利率變動型終身壽險', 3, '祝壽', '祝壽保險金', '分情況（看原文）', '第十八條被保險人於本契約有效期間內且在保險年齡屆滿一百一十歲仍生存者，本公司按下列二者之最大值給付祝壽保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽紅運長樂增額分紅終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十三條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽紅運長樂增額分紅終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽富利傳家利率變動型終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付「身故保險金」後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽富利傳家利率變動型終身壽險', 2, '特定重大疾病', '特定重大疾病保險金', '保額 × 5%', '第十三條被保險人於等待期間屆滿後或復效日起之本契約有效期間內，經醫院醫師診斷確定罹患第二條第十八款所約定之特定重大疾病者，本公司按第二條第十九款所約定之保險事故日當時之總保險金額的百分之五給付「特定重大疾病保險金」。'),
  ('fubon', '富邦人壽富利傳家利率變動型終身壽險', 3, '完全失能', '完全失能保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付「完全失能保險金」後，本契約效力即行終止：一、年繳保險費總和i。'),
  ('fubon', '富邦人壽富利傳家利率變動型終身壽險', 4, '祝壽', '祝壽保險金', '分情況（看原文）', '第十七條被保險人於本契約有效期間內且在保險年齡屆滿一百一十歲仍生存者，本公司按下列二者之最大值給付「祝壽保險金」後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽圓滿鑽利率變動型增額終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十二條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之總保險金額(以萬元為單位)，乘以本保險標準體保險費費率後所得之躉繳保險費之總額。'),
  ('fubon', '富邦人壽圓滿鑽利率變動型增額終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：ICB11402215/9商品代號：ICB一、完全失能診斷確定時之總保險金額(以萬元為單位)，乘以本保險標準體保險費費率後所得之躉繳保險'),
  ('fubon', '富邦人壽圓滿鑽利率變動型增額終身壽險', 3, '大眾運輸交通工具意外身故保險金或喪葬費用', '大眾運輸交通工具意外身故保險金或喪葬費用保險金', NULL, '第二十二條被保險人因下列原因致成死亡時，本公司不負給付「大眾運輸交通工具意外身故保險金或喪葬費用保險金」的責任：一、要保人、被保險人的故意行為。'),
  ('fubon', '富邦人壽華富紅運分紅終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十三條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽華富紅運分紅終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽鴻運久久分紅終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十三條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽鴻運久久分紅終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽全鑫如意保險', 1, '非意外傷害事故', '非意外傷害事故保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間且於下列保單年度，非因意外傷害事故身故或致成附表二所列完全失能程度之一者，本公司按下列約定給付「非意外傷害事故保險金」後，本契約之效力即行終止：一、第一保單年度內，按身故或致成附表二所列完全失能程度之一時之當年度保險金額給付。'),
  ('fubon', '富邦人壽全鑫如意保險', 2, '非意外傷害事故保險金或喪葬費用', '非意外傷害事故保險金或喪葬費用保險金', NULL, '第十二條被保險人在本契約有效期間內失蹤者，如經法院宣告死亡時，本公司根據判決內所確定死亡時日為準，依第十五條約定給付「非意外傷害事故保險金或喪葬費用保險金」；'),
  ('fubon', '富邦人壽全鑫如意保險', 3, '意外傷害身故保險金或喪葬費用', '意外傷害身故保險金或喪葬費用保險金', NULL, '如要保人或受益人能提出證明文件，足以認為被保險人極可能因意外傷害事故而死亡者，本公司應依意外傷害事故發生日為準，依第十四條約定給付「意外傷害身故保險金或喪葬費用保險金」。'),
  ('fubon', '富邦人壽全鑫如意保險', 4, '意外失能', '意外傷害失能保險金', '保額 × 附表比例', '被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表一所列二至十一級失能程度之一者，經醫院醫師診斷確定，本公司以失能診斷確定日為準，按保險金額乘以附表一所列二至十一級失能程度給付比例計算所得之金額給付「意外傷害失能保險金」。'),
  ('fubon', '富邦人壽全鑫如意保險', 5, '意外身故', '意外傷害身故保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內遭受第二條約定的一般意外傷害事故或搭乘大眾運輸交通工具所發生之意外傷害事故，自意外傷害事故發生之日起一百八十日以內身故者，本公司按下表約定給付「意外傷害身故保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽全鑫如意保險', 6, '滿期', '滿期保險金', '保額 × 1.06', '第十七條被保險人於本契約有效期間且保險期間屆滿時仍生存者，本公司按當年度保險金額的一點零六倍給付「滿期保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽豐盛年年利率變動型終身保險', 1, '身故', '身故保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、年繳保險費總和扣除累計已領生存保險金總額後之餘額。'),
  ('fubon', '富邦人壽豐盛年年利率變動型終身保險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十六條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、年繳保險費總和扣除累計已領生存保險金總額後之餘額。'),
  ('fubon', '富邦人壽豐盛年年利率變動型終身保險', 3, '大眾運輸交通工具意外身故保險金或喪葬費用', '大眾運輸交通工具意外身故保險金或喪葬費用保險金', NULL, '第二十九條被保險人因下列原因致成死亡時，本公司不負給付「大眾運輸交通工具意外身故保險金或喪葬費用保險金」的責任：一、要保人、被保險人的故意行為。'),
  ('fubon', '富邦人壽美好利外幣利率變動型增額終身壽險', 1, '身故', '身故保險金', '取較高：保額 × 1／保單價值', '第十五條被保險人於本契約有效且於繳費期間內身故者，本公司按下列二者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。二、身故時之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。被保險人於本契約有效且於繳費期間屆滿後身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。二、年繳保險費總和之一點零三倍。三、身故時之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。訂立本契約時，以實際年齡未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人實際年齡滿十五足歲之日起發生效力；被保險人'),
  ('fubon', '富邦人壽美好利外幣利率變動型增額終身壽險', 2, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值', '第十六條被保險人於本契約有效且於繳費期間內致成附表三所列完全失能程度之一者，本公司按下列二者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。二、完全失能診斷確定時之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。被保險人於本契約有效且於繳費期間屆滿後致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。二、年繳保險費總和之一點零三倍。三、完全失能診斷確定時之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。張【分期定期保險金給付】第十七條本契約身故保險金或完全失能保險金為分期'),
  ('fubon', '富邦人壽美好利外幣利率變動型增額終身壽險', 3, '祝壽', '祝壽保險金', '保額 × 1', '第十八條被保險人於本契約有效期間內且在保險年齡屆滿一百一十歲仍生存者，本公司按保險年齡屆滿一百一十歲時之當年度保險金額給付祝壽保險金後，本契約效力即行終止。'),
  ('fubon', '富邦人壽智富紅運外幣分紅終身壽險', 1, '身故', '身故保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽智富紅運外幣分紅終身壽險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十六條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、年繳保險費總和。'),
  ('fubon', '富邦人壽紅運滿滿外幣分紅終身保險', 1, '身故', '身故保險金', '分情況（看原文）', '第十六條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽紅運滿滿外幣分紅終身保險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十七條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 1, '身故', '身故保險金或喪葬費用保險金', '取較高：保額 × 1／保單價值', '第十九條被保險人於本契約有效期間內身故者，本公司按下列二者之最大值給付「身故保險金」後，本契約效力即行終止：一、當年度保險金額。二、身故時之保單當年度末之保單價值準備金。訂立本契約時，以實際年齡未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人實際年齡滿十五足歲之日起發生效力；被保險人實際年齡滿十五足歲前死亡者，其身故保險金變更為喪葬費用保險金。前項實際年齡未滿十五足歲之被保險人如有於民國九十九年二月三日(不含)前訂立之保險契約，其喪葬費用保險金之給付依下列方式辦理：一、被保險人於民國九十九年二月三日(不含)前訂立之保險契約，喪葬費用保險金額大於或等於遺產及贈與稅法'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 2, '完全失能關懷', '完全失能關懷保險金', '保額 × 15', '第十四條被保險人於本契約有效期間內因第二條約定的疾病或意外傷害事故，經醫院醫師診斷確定符合附表二所列完全失能程度之一，且於完全失能診斷確定日仍生存者，本公司按完全失能診斷確定日當時之保險金額的十五倍給付「完全失能關懷保險金」，且本契約有效期間內以給付一次為限。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 3, '長期照顧一次', '長期照顧一次保險金', '保額 × 15', '第十六條被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司按免責期間屆滿時之保險金額的十五倍，給付「長期照顧一次保險金」，且本契約有效期間內以給付一次為限。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 4, '完全失能生活扶助', '完全失能生活扶助保險金', '保額 × 2', '第十五條被保險人於本契約有效期間內因第二條約定的疾病或意外傷害事故，經醫院醫師診斷確定致成附表二所列完全失能程度之一，且於完全失能診斷確定日仍生存者，本公司於完全失能診斷確定日起一年內之每一週月日（不論被保險人生存與否），按月依當時之保險金額的二倍乘以附表三累計給付年度對應之係數，依計算所得之金額給付「完全失能生活扶助保險金」。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 5, '長期照顧分期', '長期照顧分期保險金', '保額 × 2', '第十七條被保險人於本契約有效期間內，經醫院專科醫師診斷確定符合第二條約定之「長期照顧狀態」，並於免責期間屆滿時仍生存且持續符合「長期照顧狀態」者，本公司於免責期間屆滿翌日及一年內之每一週月日（不論被保險人生存與否），按月依當時之保險金額的二倍乘以附表三累計給付年度對應之係數，依計算所得之金額給付「長期照顧分期保險金」。'),
  ('fubon', '富邦人壽詠馨滿溢長期照顧終身壽險', 6, '祝壽', '祝壽保險金', '保額 × 1', '第二十條被保險人於本契約有效期間內且保險年齡屆滿九十九歲仍生存者，本公司按當年度保險金額給付「祝壽保險金」後，本契約效力即行終止。'),
  ('fubon', '富邦人壽優富年年分紅養老保險', 1, '身故', '身故保險金', '分情況（看原文）', '第十四條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即PAJ11501015/13商品代號：PAJ行終止：一、身故時之當年度保險金額。'),
  ('fubon', '富邦人壽優富年年分紅養老保險', 2, '完全失能', '完全失能保險金', '分情況（看原文）', '第十五條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。'),
  ('fubon', '富邦人壽美富優退外幣分紅終身保險', 1, '身故', '身故保險金', '取較高：保額 × 1／保單價值／保費 × 1.06', '第十六條被保險人於本契約有效期間內身故者，本公司按下列三者之最大值給付身故保險金後，本契約效力即行終止：一、身故時之當年度保險金額。二、身故時之保單當年度末之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。三、年繳保險費總和之一點零六倍扣除累計已領生存保險金總額後之餘額。要保人選擇辦理減少保險金額者，於計算前項身故保險金而依約定有扣除累計已領之生存保險金之必要時，改以辦理減少保險金額後，被保險人發生約定保險事故時之保險金額計算之。訂立本契約時，以實際年齡未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人實際年齡滿十五足歲之日起發生效力；被保險人實'),
  ('fubon', '富邦人壽美富優退外幣分紅終身保險', 2, '生命末期提前給付', '生命末期提前給付保險金', '取較高：保額 × 1／保單價值／保費 × 1.06', '第十七條被保險人於本契約有效期間內，經醫院專科醫師診斷確定，且經本公司審查確認，依目前醫療技術無法治癒且根據醫學及臨床經驗，其平均存活期在六個月以下者，本公司按下列三者之最大值給付生命末期提前給付保險金後，本契約效力即行終止：一、生命末期診斷確定時之當年度保險金額。二、生命末期診斷確定時之保單當年度末之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。三、年繳保險費總和之一點零六倍扣除累計已領生存保險金總額後之餘額。要保人選擇辦理減少保險金額者，於計算前項生命末期提前給付保險金而依約定有扣除累計已領之生存保險金之必要時，改以辦理減少保險金額後，被保險人發生約定保險事故時之總保險金額計算之。【保險範圍：完全失能保險金的給付】第十八條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下'),
  ('fubon', '富邦人壽美富優退外幣分紅終身保險', 3, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值／保費 × 1.06', '第十八條被保險人於本契約有效期間內致成附表三所列完全失能程度之一者，本公司按下列三者之最大值給付完全失能保險金後，本契約效力即行終止：一、完全失能診斷確定時之當年度保險金額。二、完全失能診斷確定時之保單當年度末之總保單價值準備金乘上當時保險年齡對應附表二之給付比率所得之數額。三、年繳保險費總和之一點零六倍扣除累計已領生存保險金總額後之餘額。要保人選擇辦理減少保險金額者，於計算前項完全失能保險金而依約定有扣除累計已領之生存保險金之必要時，改以辦理減少保險金額後，被保險人發生約定保險事故時之保險金額計算之。【分期定期保險金給付】第十九條本契約身故保險金或完全失能保險金為分期定期給付者，本公司於分期定期給付開始日及分期定期給付開'),
